  'This document curates a Year 2 undergraduate Organic Chemistry / Biochemistry course for Kinesiology. The course is a foundational requirement for movement-science programs, with core coverage of carbon structures, stereochemistry, organic reactions, biomolecules, enzyme kinetics, glycolysis, the TCA cycle, bioenergetics, and metabolism. The syllabus includes prerequisite chemistry review, pH and buffering, biochemical methods, nucleic acids and molecular adaptation, integrated metabolism, sport nutrition connections, and exercise-physiology applications. Designed as a 15-module second-year course for kinesiology students. Each module can map to one week in a semester format, with problem sets, molecular-model activities, short wet-lab or virtual-lab exercises, metabolism diagrams, nutrition claim critiques, and a final applied case.',
  $ocbjson${"slug": "organic-chemistry-biochemistry", "title": "Organic Chemistry / Biochemistry", "description": "This document curates a Year 2 undergraduate Organic Chemistry / Biochemistry course for Kinesiology. The course is a foundational requirement for movement-science programs, with core coverage of carbon structures, stereochemistry, organic reactions, biomolecules, enzyme kinetics, glycolysis, the TCA cycle, bioenergetics, and metabolism. The syllabus includes prerequisite chemistry review, pH and buffering, biochemical methods, nucleic acids and molecular adaptation, integrated metabolism, sport nutrition connections, and exercise-physiology applications. Designed as a 15-module second-year course for kinesiology students. Each module can map to one week in a semester format, with problem sets, molecular-model activities, short wet-lab or virtual-lab exercises, metabolism diagrams, nutrition claim critiques, and a final applied case.", "topics": [{"id": "af16cf6e-a47f-4781-b50c-7541b3f8914f", "type": "topic", "title": "Chemical Foundations for Kinesiology and Health Sciences", "description": "Refresh the chemistry language students need to understand biomolecules, physiology, nutrition, and metabolism.", "children": [{"id": "41fef365-3cea-4c64-ae15-b7012ddcb396", "type": "subtopic", "title": "Atomic and molecular literacy", "description": "Students refresh the chemistry vocabulary that lets them read biochemical and physiological explanations with confidence.", "children": [{"id": "cc1b96c1-188c-4807-8738-0f16f954fcad", "type": "concept", "title": "Atoms, ions, isotopes, molecules, and compounds"}, {"id": "44b255d5-f2b9-4d4f-97fa-ba21e12fb9fc", "type": "concept", "title": "Electrons, valence, electronegativity, and polarity"}, {"id": "251b30e9-6520-402b-9beb-9d213309dbd2", "type": "concept", "title": "Moles, concentration, and biologically relevant units"}]}, {"id": "70e53b3b-f1d0-448f-94f0-b19732c7a845", "type": "subtopic", "title": "Bonding and intermolecular forces", "description": "The point is to explain why molecules dissolve, fold, bind, and react in living systems.", "children": [{"id": "96006a36-25ec-4c02-a46d-d435a20280b7", "type": "concept", "title": "Covalent, ionic, hydrogen, and van der Waals interactions"}, {"id": "d62f6a96-7dc3-4d2a-840f-9a6bfbcb8a60", "type": "concept", "title": "Hydrophilic, hydrophobic, amphipathic, and charged molecules"}, {"id": "f8e1845e-8e5d-40bf-b19f-8e411db35efb", "type": "concept", "title": "Solubility, membranes, protein folding, and ligand binding"}]}, {"id": "5b9639b9-a198-445e-b3ed-894b20a5122a", "type": "subtopic", "title": "Quantitative chemistry for health science", "description": "Learners practice the calculations that appear in labs, physiology, nutrition, and exercise metabolism.", "children": [{"id": "e7f54e13-d5ad-4325-b1c0-e4a236c2aa10", "type": "concept", "title": "Stoichiometry and limiting reagents"}, {"id": "45750fea-ba17-4ddf-b5ec-b89e44585a87", "type": "concept", "title": "Molarity, dilution, osmolarity, and percent solutions"}, {"id": "2379f136-416d-4f23-a4f9-63afac902ba9", "type": "concept", "title": "Energy units, calories, joules, and oxygen-equivalent thinking"}]}]}, {"id": "91579224-4b14-4ebe-8aaa-796c4b57d23c", "type": "topic", "title": "Carbon Bonding, Functional Groups, and Molecular Properties", "description": "Build fluency with the structures and properties that make biological molecules behave the way they do.", "children": [{"id": "a5dc61d3-962b-46ab-923a-9ee78339921a", "type": "subtopic", "title": "Carbon structure and bonding", "description": "Students learn why carbon can build the molecular diversity required for life.", "children": [{"id": "8d468baa-4862-403e-8381-091f709b6b2b", "type": "concept", "title": "Tetrahedral carbon and hybridization"}, {"id": "291644c8-a12f-40f3-9003-4700dfabfbfb", "type": "concept", "title": "Single, double, and triple bonds"}, {"id": "20d864b4-d2a7-49c7-a351-a5d14d3cb60e", "type": "concept", "title": "Chains, rings, branching, and unsaturation"}]}, {"id": "3e36ba92-9c7e-4097-a50f-0b5579117fcd", "type": "subtopic", "title": "Functional groups", "description": "The gist is to recognize the chemical handles that determine biological behavior.", "children": [{"id": "4fac3caa-5577-4f25-91a3-1b3fd7569d8a", "type": "concept", "title": "Alcohols, thiols, amines, carboxylic acids, aldehydes, ketones, esters, amides, phosphates, and sulfhydryls"}, {"id": "d6adbfc5-1b77-4695-b6ec-4a47c7eeca2a", "type": "concept", "title": "Charge, polarity, hydrogen bonding, and reactivity"}, {"id": "94734c16-1db5-469f-b3ab-72c0d9adfc6a", "type": "concept", "title": "Functional groups in carbohydrates, lipids, proteins, and nucleotides"}]}, {"id": "45cd1d73-1d0b-4734-8f83-19ae0bd578ff", "type": "subtopic", "title": "Structure-property relationships", "description": "Students connect molecular form to solubility, membrane crossing, storage, and metabolism.", "children": [{"id": "e79fb3d8-7db2-464e-8e5e-8a41ac3910d1", "type": "concept", "title": "Molecular size and shape"}, {"id": "f9c39a7e-5d95-47dc-9a03-caff36788b09", "type": "concept", "title": "Acid-base behavior and ionization"}, {"id": "85ab1cf3-c658-481c-813b-e38484c33d4c", "type": "concept", "title": "Partitioning between water, blood, cells, membranes, and adipose tissue"}]}]}, {"id": "a6e3d4d2-65d9-4640-9acf-6f1662b95d34", "type": "topic", "title": "Stereochemistry, Isomerism, and Molecular Recognition", "description": "Explain why three-dimensional molecular shape matters for enzymes, receptors, drugs, fuels, and tissues.", "children": [{"id": "24054d0f-cba3-46fc-b7fa-9e896247b827", "type": "subtopic", "title": "Isomers in biology", "description": "Students learn that molecules with the same formula can have very different effects in the body.", "children": [{"id": "138861c2-e695-4e35-8c22-26be0f9dbe74", "type": "concept", "title": "Constitutional isomers"}, {"id": "9d49c267-794c-4b89-b373-4154759de230", "type": "concept", "title": "Cis-trans and E/Z isomerism"}, {"id": "a492b31c-a89d-4a22-acb4-14d447b28a71", "type": "concept", "title": "Chirality, enantiomers, diastereomers, and meso concepts"}]}, {"id": "0613b570-3220-4369-b905-01d287dc6896", "type": "subtopic", "title": "Molecular recognition", "description": "This subtopic explains why enzymes, receptors, transporters, and drugs are shape-selective.", "children": [{"id": "27b90902-e194-4c4e-8f95-e54496a66d80", "type": "concept", "title": "Lock-and-key and induced-fit ideas"}, {"id": "22c72a09-a09e-4f2c-9010-3d37fab43b4b", "type": "concept", "title": "Binding pockets and complementarity"}, {"id": "bd18477b-ce7f-4e46-80a2-012bdc719928", "type": "concept", "title": "Stereospecific metabolism and signaling"}]}, {"id": "3e63da96-8bf4-470b-9b70-b9d91aebd61b", "type": "subtopic", "title": "Applied stereochemistry", "description": "Learners see stereochemistry in nutrition, pharmacology, exercise physiology, and health claims.", "children": [{"id": "34d7a72f-2593-4e41-9fe4-59741785b058", "type": "concept", "title": "D- and L-sugars and amino acids"}, {"id": "d00a95c1-f214-4143-a034-3efc457cabc6", "type": "concept", "title": "Cis and trans fatty acids"}, {"id": "1eece36d-d553-40b9-a918-a759ca7b3b53", "type": "concept", "title": "Lactate, amino acid supplements, and drug examples"}]}]}, {"id": "0240307f-4e2a-4b15-ac52-6f3f94c8d918", "type": "topic", "title": "Organic Reaction Logic and Mechanisms in Biological Context", "description": "Use reaction patterns to understand biochemical transformations rather than memorizing disconnected facts.", "children": [{"id": "353ea227-ea5a-4de7-aeb9-4aeb1b7cf196", "type": "subtopic", "title": "Reaction patterns", "description": "Students learn reaction families as reusable logic for biochemical pathways.", "children": [{"id": "e4f80902-91c6-4d26-840e-4c0331c456e5", "type": "concept", "title": "Substitution, addition, elimination, oxidation-reduction, condensation, and hydrolysis"}, {"id": "d2f66532-4393-4eb7-ae7d-968d4db36f52", "type": "concept", "title": "Nucleophiles, electrophiles, leaving groups, and catalysts"}, {"id": "9905bf70-c2a2-4e5a-bb16-2b63ad37dd22", "type": "concept", "title": "Reaction arrows and mechanism reasoning"}]}, {"id": "c65e8d9e-2e80-457b-81b5-bf6c54f7bd5f", "type": "subtopic", "title": "Biochemical transformations", "description": "The point is to make metabolism feel chemically inevitable rather than memorized.", "children": [{"id": "2833a9f6-3c56-4e5d-8d51-414aca75244c", "type": "concept", "title": "Phosphorylation and dephosphorylation"}, {"id": "690402ed-4f35-44cb-a954-43a827dfd9de", "type": "concept", "title": "Isomerization, cleavage, transfer, carboxylation, and decarboxylation"}, {"id": "dcac32f8-2ee8-4b74-9f97-9d2d8e7bc644", "type": "concept", "title": "Hydrolysis of ATP, glycogen, triglycerides, and proteins"}]}, {"id": "50a4186e-e2eb-46cb-b2d6-ec6b07d358ce", "type": "subtopic", "title": "Reaction conditions in living systems", "description": "Learners compare bench organic chemistry with enzyme-mediated chemistry in cells.", "children": [{"id": "ab3f9f7b-c7ae-421a-b1d3-12aad4c65ceb", "type": "concept", "title": "Aqueous environments, moderate temperatures, and physiological pH"}, {"id": "4a37343d-c680-4c26-9745-f1a78f6bc2dd", "type": "concept", "title": "Enzyme active sites and cofactors"}, {"id": "91ea9927-1c5b-48da-93d2-7d3ab8d76d3e", "type": "concept", "title": "Specificity, regulation, and compartmentalization"}]}]}, {"id": "19912e95-5634-4580-80f7-0c35b1c2774f", "type": "topic", "title": "Water, pH, Buffers, Acids, Bases, and Physiological Chemistry", "description": "Connect acid-base chemistry to blood, muscle, enzymes, exercise intensity, and homeostasis.", "children": [{"id": "65cb22dd-b09d-4d5a-8378-29ad0a3f0841", "type": "subtopic", "title": "Water as biological solvent", "description": "Students learn why water makes life chemistry possible and constrains how biomolecules behave.", "children": [{"id": "144eefe0-cc0a-47c2-9093-9a7cb90031f3", "type": "concept", "title": "Polarity and hydrogen bonding"}, {"id": "59a73faa-9303-4e72-87a8-df6bf441bfc7", "type": "concept", "title": "Hydration shells and hydrophobic effect"}, {"id": "735c3403-2943-4881-bc4a-5c5c0c87f46a", "type": "concept", "title": "Osmosis, tonicity, and cellular volume"}]}, {"id": "a5f31a39-8d8f-457c-b1ad-2d28acfe755b", "type": "subtopic", "title": "Acids, bases, and buffers", "description": "The gist is to connect pH chemistry to enzymes, blood, exercise, and homeostasis.", "children": [{"id": "7fd7f5f4-703c-4842-bc74-e714104f5df0", "type": "concept", "title": "pH, pKa, weak acids, weak bases, and ionization"}, {"id": "8d2b3c71-294c-4f26-b86d-8a9acb33b4c7", "type": "concept", "title": "Henderson-Hasselbalch reasoning"}, {"id": "207a8182-b401-44a8-93dc-d66a13b48a56", "type": "concept", "title": "Bicarbonate, phosphate, protein, and hemoglobin buffers"}]}, {"id": "9d5c2091-66a5-4491-b7ad-5912cc5e67d3", "type": "subtopic", "title": "Exercise acid-base physiology", "description": "Learners connect chemical buffering to high-intensity work and fatigue.", "children": [{"id": "25176ecd-f738-4dc8-9ed9-0914c5786f59", "type": "concept", "title": "Carbon dioxide, ventilation, and bicarbonate"}, {"id": "ac47222f-38d5-4a2e-a878-1ff074a5c1ab", "type": "concept", "title": "Lactate and hydrogen ion misconceptions"}, {"id": "2ef3e05c-94b0-4134-8479-c4ff1bcb85ee", "type": "concept", "title": "Muscle pH, buffering capacity, and training adaptation"}]}]}, {"id": "9ef67c52-1094-4b65-ba64-e8bb296ebef0", "type": "topic", "title": "Carbohydrates, Glycobiology, and Exercise Fuel Availability", "description": "Understand carbohydrate structure, storage, digestion, and use during rest and exercise.", "children": [{"id": "e5777d17-76c9-4b2c-a0ae-fe27fd725637", "type": "subtopic", "title": "Carbohydrate structure", "description": "Students learn how simple chemical differences create different fuels and tissues.", "children": [{"id": "c94575dd-1d54-41a7-84be-18c43c7b4886", "type": "concept", "title": "Monosaccharides, disaccharides, oligosaccharides, and polysaccharides"}, {"id": "c38d9e23-04ef-4ba4-85ff-705ebceb8178", "type": "concept", "title": "Aldoses, ketoses, ring forms, and glycosidic bonds"}, {"id": "c9368a58-8554-40c0-b6c6-0ff17cc6cc76", "type": "concept", "title": "Starch, glycogen, cellulose, and fiber"}]}, {"id": "1edd884d-942d-4a5f-8dd2-36af48ac95eb", "type": "subtopic", "title": "Digestion, absorption, and storage", "description": "This subtopic connects carbohydrate chemistry to blood glucose and exercise readiness.", "children": [{"id": "b7c2be90-9a91-4d27-9bba-0a2f2aaaa0c8", "type": "concept", "title": "Digestive enzymes and intestinal absorption"}, {"id": "9b22129f-71fb-4cbf-a533-60a258612bb2", "type": "concept", "title": "Glucose transport and insulin-responsive uptake"}, {"id": "04daad83-ca81-44cb-b368-85699dd0e38a", "type": "concept", "title": "Glycogen synthesis, storage, and mobilization"}]}, {"id": "7c377874-b704-4b1c-aa6e-9f4ff270e2d2", "type": "subtopic", "title": "Carbohydrates in exercise", "description": "Learners understand why exercise intensity, duration, and diet change carbohydrate demand.", "children": [{"id": "14e562ea-010f-4d67-9d9e-f8dc7d6f9c9b", "type": "concept", "title": "Muscle and liver glycogen"}, {"id": "6d9c4325-d1ae-48c5-8363-2b32eb0641fb", "type": "concept", "title": "Carbohydrate oxidation and sparing"}, {"id": "93b70466-5cca-4527-9819-7a9437c35a6d", "type": "concept", "title": "Fueling, recovery, and low-carbohydrate adaptation debates"}]}]}, {"id": "025a0db6-f7d0-41b9-82e5-6175f9997c82", "type": "topic", "title": "Lipids, Membranes, Signaling, and Fat Metabolism", "description": "Study lipids as membrane materials, hormones and signals, energy stores, and exercise fuels.", "children": [{"id": "b801569f-d927-43e0-bbdc-a87de5300d33", "type": "subtopic", "title": "Lipid classes and properties", "description": "Students learn why lipids are chemically diverse and biologically essential.", "children": [{"id": "772a62a6-8a09-47e0-b8b4-501c302e9364", "type": "concept", "title": "Fatty acids, triglycerides, phospholipids, cholesterol, steroids, and eicosanoids"}, {"id": "d217fa3f-eb4b-4ec2-b96a-857d57eb1dd0", "type": "concept", "title": "Saturation, chain length, cis-trans configuration, and melting behavior"}, {"id": "54488274-b0da-4a54-9a47-ce0a0e60a395", "type": "concept", "title": "Hydrophobic and amphipathic molecules"}]}, {"id": "1d595a55-ffcc-4d38-909e-34cf3dee9d91", "type": "subtopic", "title": "Membranes and signaling", "description": "The point is to connect lipid chemistry to cell structure, transport, and communication.", "children": [{"id": "f03efb8c-20dd-4bd0-9c2b-14f4276ca0f2", "type": "concept", "title": "Membrane bilayers and fluidity"}, {"id": "7af09a33-4f72-4b95-b332-937a0b7cc115", "type": "concept", "title": "Lipid rafts, receptors, transporters, and channels"}, {"id": "bb6327ca-6c0f-41e0-b1c9-e760e8166d84", "type": "concept", "title": "Steroid hormones, prostaglandins, and inflammatory signaling"}]}, {"id": "39646498-8fa0-4acc-b07a-18746456bc68", "type": "subtopic", "title": "Fat as exercise fuel", "description": "Learners trace how stored fat becomes usable energy during rest and exercise.", "children": [{"id": "c58d4d90-61cb-46b3-842d-66a3d5a0fc0b", "type": "concept", "title": "Lipolysis, transport, and albumin"}, {"id": "19601125-8e7c-48c5-bd05-801109e3451a", "type": "concept", "title": "Beta-oxidation and acetyl-CoA production"}, {"id": "e3bbf969-4fe8-4e48-acef-5e3f20c264cf", "type": "concept", "title": "Intensity, duration, training status, and fat oxidation"}]}]}, {"id": "d3b7e033-a521-4d07-b877-47d8f91fd253", "type": "topic", "title": "Amino Acids, Proteins, Structure, and Movement Function", "description": "Link protein chemistry to muscle, enzymes, transporters, connective tissue, and adaptation.", "children": [{"id": "141ec668-c865-41e4-a0d3-3b65627bf906", "type": "subtopic", "title": "Amino acid chemistry", "description": "Students learn the building blocks that drive protein structure and function.", "children": [{"id": "58dd141b-5004-4177-a5e8-cdd6a679b1e1", "type": "concept", "title": "Side-chain classes, charge, polarity, sulfur, and aromaticity"}, {"id": "6116f07d-a840-4407-852f-c9808b676f81", "type": "concept", "title": "Zwitterions, pKa, and buffering"}, {"id": "f5fe818f-9f36-49e8-9116-b8802ce0bf18", "type": "concept", "title": "Essential, nonessential, glucogenic, and ketogenic amino acids"}]}, {"id": "2764da06-6d4b-4da9-ab97-cac2f2ae7966", "type": "subtopic", "title": "Protein structure and folding", "description": "The gist is to see proteins as functional three-dimensional machines.", "children": [{"id": "fbea08e5-9e25-41ac-bda2-12b58683cb72", "type": "concept", "title": "Primary, secondary, tertiary, and quaternary structure"}, {"id": "818d504f-99e2-449c-b7f2-deeed5225b67", "type": "concept", "title": "Hydrogen bonds, ionic interactions, disulfides, and hydrophobic packing"}, {"id": "c0526f14-e282-43d3-9cde-56f30cdb8b6f", "type": "concept", "title": "Denaturation, misfolding, and chaperones"}]}, {"id": "e5b6eeb4-1e1b-4717-a102-5fc0cd748e97", "type": "subtopic", "title": "Proteins in kinesiology", "description": "Learners connect protein chemistry to movement, adaptation, and tissue repair.", "children": [{"id": "7dc3f251-b5d5-4d61-b466-2ca1bff4f45b", "type": "concept", "title": "Actin, myosin, collagen, elastin, hemoglobin, myoglobin, and enzymes"}, {"id": "25a81545-e5a4-4fb3-8070-3ff84ff6206d", "type": "concept", "title": "Muscle protein synthesis and breakdown"}, {"id": "1780516e-d9bd-4e5f-b9af-c06df076d897", "type": "concept", "title": "Training, nutrition, recovery, and injury repair"}]}]}, {"id": "591498cb-e566-4af9-a741-0b15e5f76e26", "type": "topic", "title": "Enzymes, Kinetics, Regulation, and Metabolic Control", "description": "Learn how enzymes accelerate and regulate the biochemical pathways that support movement and health.", "children": [{"id": "307c8d80-77bf-4385-b8b3-eadc4a6cbcc5", "type": "subtopic", "title": "Enzyme function", "description": "Students learn how enzymes make cellular chemistry fast, specific, and regulated.", "children": [{"id": "2bb91c81-8d38-418f-948c-e72ad340bae1", "type": "concept", "title": "Activation energy and transition states"}, {"id": "80dcc6fb-6604-499c-8209-a35c3f420e77", "type": "concept", "title": "Active sites, cofactors, coenzymes, and metal ions"}, {"id": "35766daa-fa84-4474-84c0-4133fc17a25b", "type": "concept", "title": "Specificity, saturation, and catalytic efficiency"}]}, {"id": "96365330-3a6c-444e-a56b-2eda0f444e39", "type": "subtopic", "title": "Kinetics and inhibition", "description": "This subtopic gives students a working model for interpreting enzyme behavior.", "children": [{"id": "09c4c524-81a6-4976-b138-1b2ddf5cdaa7", "type": "concept", "title": "Michaelis-Menten concepts, Km, Vmax, and turnover"}, {"id": "65f15ac2-428f-45d1-b964-ef6a7f36a8bf", "type": "concept", "title": "Competitive, noncompetitive, uncompetitive, and irreversible inhibition"}, {"id": "fb9bc380-0451-432c-b21c-2b0f570fce41", "type": "concept", "title": "Allosteric enzymes and cooperativity"}]}, {"id": "4482eca8-aeca-4c7b-b28e-5f16a5eb883a", "type": "subtopic", "title": "Regulation of metabolism", "description": "Learners connect enzyme control to exercise, fasting, feeding, and training.", "children": [{"id": "c45f30a8-c2b3-4c9e-9ccc-fcc309528f7e", "type": "concept", "title": "Substrate availability and product inhibition"}, {"id": "c567f711-b18f-45cd-b5be-4aaa47525646", "type": "concept", "title": "Covalent modification and phosphorylation"}, {"id": "679b6fcc-cdda-4f56-9f25-64b16b2e1645", "type": "concept", "title": "Hormonal regulation, compartmentalization, and rate-limiting steps"}]}]}, {"id": "d85156a3-d524-46b1-b1dc-e39682b7baa1", "type": "topic", "title": "Nucleic Acids, Gene Expression, and Molecular Adaptation", "description": "Introduce DNA, RNA, protein synthesis, and gene regulation as foundations for training adaptation and health.", "children": [{"id": "d9bcfce9-d17e-40b0-bfc4-6d7f2058e0a7", "type": "subtopic", "title": "DNA and RNA structure", "description": "Students learn the molecular basis of inheritance and protein production.", "children": [{"id": "f0100719-eac2-4091-b5f7-e51c031b83e4", "type": "concept", "title": "Nucleotides, bases, sugars, phosphate backbone, and base pairing"}, {"id": "c3752d8d-9480-4c6c-a7fa-e205f5c60e46", "type": "concept", "title": "DNA double helix and RNA forms"}, {"id": "499430ef-10d7-4410-876e-01102eba5c8f", "type": "concept", "title": "ATP and nucleotide derivatives as energy and signaling molecules"}]}, {"id": "bc3bd2ce-192a-4113-a5f5-8e9f2b986709", "type": "subtopic", "title": "Gene expression", "description": "The point is to understand how molecular information becomes functional protein.", "children": [{"id": "a055538c-d10c-4f05-bf89-286403169b39", "type": "concept", "title": "Replication, transcription, translation, and the genetic code"}, {"id": "e4675ec2-2655-4fcb-bbd9-0d2857e5e70d", "type": "concept", "title": "mRNA, tRNA, rRNA, ribosomes, and post-translational modification"}, {"id": "a9ed5410-318d-45ac-9fee-ede7e93bce40", "type": "concept", "title": "Regulatory elements and gene-expression control"}]}, {"id": "fac01a26-601a-4417-92e8-45a510c558d9", "type": "subtopic", "title": "Adaptation and health relevance", "description": "Learners connect molecular biology to training response, disease risk, and personalized health.", "children": [{"id": "31a16a4f-c669-46d0-b457-33ea0ab9863e", "type": "concept", "title": "Exercise-induced gene expression"}, {"id": "7baf3e16-97de-4d12-812e-9dd61bd1dfa4", "type": "concept", "title": "Mitochondrial biogenesis and muscle phenotype"}, {"id": "8b3d4d2a-177a-440f-9998-071da59e9f99", "type": "concept", "title": "Genetics, epigenetics, nutrigenomics, and ethical limits of prediction"}]}]}, {"id": "fe31e7cf-a26e-4997-bbd6-018201c90984", "type": "topic", "title": "Thermodynamics, Redox Chemistry, ATP, and Bioenergetics", "description": "Explain how energy, electrons, ATP, and coupled reactions drive cellular work.", "children": [{"id": "b60b0bbe-0d64-476e-9f08-ded54a651d91", "type": "subtopic", "title": "Energy principles", "description": "Students learn the thermodynamic rules behind cellular work.", "children": [{"id": "af492826-d87d-473a-94bc-f46dfc164dd5", "type": "concept", "title": "Free energy, enthalpy, entropy, and spontaneity"}, {"id": "2a018901-f94f-49a4-8492-0686b7b96db9", "type": "concept", "title": "Exergonic and endergonic reactions"}, {"id": "ff09abf9-f7ed-4361-8bf7-addefd5ce718", "type": "concept", "title": "Coupled reactions and metabolic directionality"}]}, {"id": "8c53ac70-4684-410b-b1ea-a46f54eced0f", "type": "subtopic", "title": "ATP and high-energy compounds", "description": "The gist is to understand ATP as an energy-transfer currency rather than a simple fuel tank.", "children": [{"id": "c0204194-363b-438f-930a-e43ca6ef5c51", "type": "concept", "title": "ATP hydrolysis and phosphorylation potential"}, {"id": "bf413c6e-e516-49b3-a15a-6d86a2a92cd4", "type": "concept", "title": "Creatine phosphate and rapid energy buffering"}, {"id": "fa336c8d-760e-41af-a043-4fd25d89bf59", "type": "concept", "title": "Substrate-level and oxidative phosphorylation"}]}, {"id": "4796c64f-625e-4510-bde9-9a4ed1e392fe", "type": "subtopic", "title": "Redox chemistry", "description": "Learners connect electron transfer to mitochondrial energy production and oxidative stress.", "children": [{"id": "c7d9ee73-9767-4ee8-9b87-637dfd1748de", "type": "concept", "title": "Oxidation, reduction, electron carriers, NADH, FADH2, and NADPH"}, {"id": "46cb80df-47be-4f78-9095-445a164830b9", "type": "concept", "title": "Redox potential and electron flow"}, {"id": "7a4c2ea5-b6c6-4538-90e1-333431454a4c", "type": "concept", "title": "Reactive oxygen species, antioxidants, and signaling"}]}]}, {"id": "8fd493f8-7b1e-4cb3-8d32-a15ac47ba52a", "type": "topic", "title": "Glycolysis, Glycogen Metabolism, and Anaerobic Energy Systems", "description": "Trace carbohydrate breakdown and storage in relation to exercise intensity and fatigue.", "children": [{"id": "9a01da3a-4c24-4b86-8acf-bb2bd70d5974", "type": "subtopic", "title": "Glycolysis pathway logic", "description": "Students trace glucose breakdown in a way that supports physiology and exercise applications.", "children": [{"id": "56e0abae-012f-4db9-917a-4325bf97df55", "type": "concept", "title": "Investment and payoff phases"}, {"id": "61d0d013-a930-4bc4-b6c6-a392cafb0692", "type": "concept", "title": "Key intermediates and irreversible steps"}, {"id": "5c91cf19-4b7e-4bd9-9de1-dac1c516450a", "type": "concept", "title": "NADH production and pyruvate formation"}]}, {"id": "e63ec4bc-1411-4f69-8bc0-58b8b5996284", "type": "subtopic", "title": "Anaerobic metabolism and lactate", "description": "This subtopic clarifies how high-intensity exercise maintains ATP production when oxygen delivery is limiting.", "children": [{"id": "a3489a46-22ee-44cf-9f9f-37900c0e37fd", "type": "concept", "title": "Lactate dehydrogenase and NAD+ regeneration"}, {"id": "08f12927-30e7-459f-8743-e09d15670f50", "type": "concept", "title": "Lactate shuttle concepts"}, {"id": "c5daef48-0fbe-4e54-bc50-8ad5174194f1", "type": "concept", "title": "Acidosis, fatigue, and common misconceptions"}]}, {"id": "aab89297-c6ee-4cd8-956d-24fd748e2adb", "type": "subtopic", "title": "Glycogen metabolism", "description": "Learners connect storage chemistry to training, competition, and recovery.", "children": [{"id": "54e0d370-f110-45c6-b97b-e02c74625944", "type": "concept", "title": "Glycogenesis and glycogenolysis"}, {"id": "75cca06c-24c6-4159-bdcb-edfdb06bd356", "type": "concept", "title": "Muscle versus liver glycogen"}, {"id": "a04c9264-c14e-4432-ae57-9ac67ef2587b", "type": "concept", "title": "Glycogen depletion, carbohydrate loading, and recovery nutrition"}]}]}, {"id": "0afaafa0-760a-4e50-83c4-14994c3042b7", "type": "topic", "title": "TCA Cycle, Oxidative Phosphorylation, Fat and Protein Metabolism", "description": "Integrate aerobic metabolism, mitochondrial function, substrate use, and prolonged exercise physiology.", "children": [{"id": "709cbe99-572d-46e1-a593-72ced809c33a", "type": "subtopic", "title": "TCA cycle and mitochondrial integration", "description": "Students learn how multiple fuels converge on mitochondrial metabolism.", "children": [{"id": "8714cc81-044e-4e9a-bff4-d17a25d3473d", "type": "concept", "title": "Acetyl-CoA entry and carbon flow"}, {"id": "d4cc4644-765f-4291-804d-d923adf8f1c7", "type": "concept", "title": "NADH, FADH2, and CO2 production"}, {"id": "f56d5669-f8e6-41dc-90d3-6349702aaa0a", "type": "concept", "title": "Anaplerosis, cataplerosis, and pathway integration"}]}, {"id": "e16c69f8-a967-4fa0-9693-d31b1dfc5349", "type": "subtopic", "title": "Electron transport and oxidative phosphorylation", "description": "The point is to understand how oxygen supports high-yield ATP production.", "children": [{"id": "feafc36e-dea6-4a9e-bfc2-1f9ec1e0aa1a", "type": "concept", "title": "Electron transport chain complexes"}, {"id": "59d7e961-790f-4f45-a7d1-6cc1ba63e7dc", "type": "concept", "title": "Proton gradient, ATP synthase, and chemiosmosis"}, {"id": "72274ba4-0c78-4e20-81a2-a064314b322b", "type": "concept", "title": "Oxygen consumption, efficiency, and mitochondrial adaptations"}]}, {"id": "95e1b5b4-6266-4b5e-bf33-6fbb85c9929a", "type": "subtopic", "title": "Fat and protein metabolism", "description": "Learners place fatty acids and amino acids into the whole energy map.", "children": [{"id": "1f109107-b388-4555-b36e-29222bb03205", "type": "concept", "title": "Beta-oxidation and ketone bodies"}, {"id": "dd29f14d-a5a1-415d-b7ba-ec955431fa1b", "type": "concept", "title": "Amino acid transamination, deamination, and urea cycle basics"}, {"id": "47d70cef-0ebb-4ebc-8b43-4b5963469f55", "type": "concept", "title": "Substrate use during fasting, endurance exercise, and energy deficit"}]}]}, {"id": "a8b0c960-7d7f-423c-8525-374220f581e2", "type": "topic", "title": "Integrated Metabolism, Hormonal Regulation, Nutrition, and Training Adaptation", "description": "Understand how fed, fasted, resting, exercising, and training states reorganize metabolism.", "children": [{"id": "0e03ce03-0dfc-4cd8-8b22-bc925364d702", "type": "subtopic", "title": "Fed, fasted, and exercise states", "description": "Students learn that metabolism is dynamic and context dependent.", "children": [{"id": "ae8423b7-f125-4ca5-8d81-df4afc1fb239", "type": "concept", "title": "Absorptive and postabsorptive metabolism"}, {"id": "3206c9e4-21c0-489e-ada1-dc00de4bfb87", "type": "concept", "title": "Rest, low-intensity, high-intensity, and prolonged exercise"}, {"id": "935b256a-8f4c-432e-af18-342598e87ad8", "type": "concept", "title": "Recovery and sleep-related metabolism"}]}, {"id": "1f4d15b7-4fb9-4c27-b51b-886077b172a0", "type": "subtopic", "title": "Hormonal regulation", "description": "The gist is to connect endocrine signals to fuel selection and adaptation.", "children": [{"id": "fce32985-9e7b-45d1-a816-18ac7f7d79e4", "type": "concept", "title": "Insulin, glucagon, epinephrine, cortisol, growth hormone, thyroid hormone, and sex hormones"}, {"id": "b5800f10-b34a-42fc-bf0e-686307202afe", "type": "concept", "title": "AMPK, mTOR, and cellular nutrient-sensing concepts"}, {"id": "ce27f56b-dad9-4a9f-89b6-8b95202b10ec", "type": "concept", "title": "Stress, overreaching, and energy availability"}]}, {"id": "e291e0a2-888e-4e77-85d6-5fc4117792e4", "type": "subtopic", "title": "Nutrition and training applications", "description": "Learners translate biochemical principles into cautious, evidence-based health and performance thinking.", "children": [{"id": "a7daa7d4-7f35-4c62-af18-4f35ad3009e0", "type": "concept", "title": "Macronutrient timing and recovery"}, {"id": "ad926588-fc56-4e13-a040-14ee9f392d04", "type": "concept", "title": "Supplements, ergogenic aids, and safety"}, {"id": "d148c901-7dd4-43ad-905e-49a9f30ef12e", "type": "concept", "title": "Body composition, RED-S, diabetes, metabolic syndrome, and referral boundaries"}]}]}, {"id": "88c04dd7-a4a9-4ca2-8c8c-ac87553f3a6a", "type": "topic", "title": "Biochemical Methods, Data Interpretation, Case Applications, and Capstone", "description": "Apply course concepts through labs, data, clinical-exercise scenarios, nutrition claims, and integrative cases.", "children": [{"id": "3423b6c1-2b61-4b65-8c83-85268f881279", "type": "subtopic", "title": "Biochemical methods", "description": "Students learn how biochemical knowledge is measured rather than merely asserted.", "children": [{"id": "d976839e-e2d9-491a-96ad-2b7b761d2d18", "type": "concept", "title": "Spectrophotometry, chromatography, electrophoresis, and enzyme assays"}, {"id": "c4f40c67-50d3-4042-819e-cbc3b77ca109", "type": "concept", "title": "Blood glucose, lactate, ketones, lipids, hemoglobin, and creatine kinase"}, {"id": "cafcdf01-6d5a-495d-95e9-9fc5aa7a9b29", "type": "concept", "title": "Sample handling, controls, calibration, and error"}]}, {"id": "5b0f0075-587f-4ccc-a924-085f5e2d53d8", "type": "subtopic", "title": "Data and evidence literacy", "description": "This subtopic helps learners interpret graphs, claims, and lab results with care.", "children": [{"id": "bb9353ea-338d-477f-9a4f-eef1ec461fea", "type": "concept", "title": "Dose-response curves and Lineweaver-Burk limitations"}, {"id": "fa9e0dde-8ab3-4244-9918-179a5f980ad2", "type": "concept", "title": "Units, normalization, reference ranges, and biological variability"}, {"id": "df7a6647-424d-4271-bc1a-03bc434d7181", "type": "concept", "title": "Primary literature, supplement claims, and conflict of interest"}]}, {"id": "ec51688e-e08f-497d-8af2-3bf964e61e54", "type": "subtopic", "title": "Kinesiology capstone cases", "description": "Learners integrate organic chemistry and biochemistry with movement, nutrition, and physiology.", "children": [{"id": "75d03acb-3731-4bce-b91f-432c07a56f98", "type": "concept", "title": "Fuel use across exercise intensities"}, {"id": "4ae07580-3ac5-4b32-9ddf-a3d5e0115f88", "type": "concept", "title": "Training adaptation and mitochondrial biogenesis"}, {"id": "c6ee5529-9d38-4244-99ff-5740fff66bf6", "type": "concept", "title": "Metabolic health, sport nutrition, fatigue, and recovery scenarios"}]}]}], "dbBacked": true}$ocbjson$::jsonb,
  true,
  false,
  'course',
  'public'
where not exists (
  select 1 from public.learning_paths where slug = 'organic-chemistry-biochemistry'
);

update public.learning_paths
set
  title = 'Organic Chemistry / Biochemistry',
  goal = 'Organic Chemistry / Biochemistry',
  summary = 'This document curates a Year 2 undergraduate Organic Chemistry / Biochemistry course for Kinesiology. The course is a foundational requirement for movement-science programs, with core coverage of carbon structures, stereochemistry, organic reactions, biomolecules, enzyme kinetics, glycolysis, the TCA cycle, bioenergetics, and metabolism. The syllabus includes prerequisite chemistry review, pH and buffering, biochemical methods, nucleic acids and molecular adaptation, integrated metabolism, sport nutrition connections, and exercise-physiology applications. Designed as a 15-module second-year course for kinesiology students. Each module can map to one week in a semester format, with problem sets, molecular-model activities, short wet-lab or virtual-lab exercises, metabolism diagrams, nutrition claim critiques, and a final applied case.',
  data = $ocbjson${"slug": "organic-chemistry-biochemistry", "title": "Organic Chemistry / Biochemistry", "description": "This document curates a Year 2 undergraduate Organic Chemistry / Biochemistry course for Kinesiology. The course is a foundational requirement for movement-science programs, with core coverage of carbon structures, stereochemistry, organic reactions, biomolecules, enzyme kinetics, glycolysis, the TCA cycle, bioenergetics, and metabolism. The syllabus includes prerequisite chemistry review, pH and buffering, biochemical methods, nucleic acids and molecular adaptation, integrated metabolism, sport nutrition connections, and exercise-physiology applications. Designed as a 15-module second-year course for kinesiology students. Each module can map to one week in a semester format, with problem sets, molecular-model activities, short wet-lab or virtual-lab exercises, metabolism diagrams, nutrition claim critiques, and a final applied case.", "topics": [{"id": "af16cf6e-a47f-4781-b50c-7541b3f8914f", "type": "topic", "title": "Chemical Foundations for Kinesiology and Health Sciences", "description": "Refresh the chemistry language students need to understand biomolecules, physiology, nutrition, and metabolism.", "children": [{"id": "41fef365-3cea-4c64-ae15-b7012ddcb396", "type": "subtopic", "title": "Atomic and molecular literacy", "description": "Students refresh the chemistry vocabulary that lets them read biochemical and physiological explanations with confidence.", "children": [{"id": "cc1b96c1-188c-4807-8738-0f16f954fcad", "type": "concept", "title": "Atoms, ions, isotopes, molecules, and compounds"}, {"id": "44b255d5-f2b9-4d4f-97fa-ba21e12fb9fc", "type": "concept", "title": "Electrons, valence, electronegativity, and polarity"}, {"id": "251b30e9-6520-402b-9beb-9d213309dbd2", "type": "concept", "title": "Moles, concentration, and biologically relevant units"}]}, {"id": "70e53b3b-f1d0-448f-94f0-b19732c7a845", "type": "subtopic", "title": "Bonding and intermolecular forces", "description": "The point is to explain why molecules dissolve, fold, bind, and react in living systems.", "children": [{"id": "96006a36-25ec-4c02-a46d-d435a20280b7", "type": "concept", "title": "Covalent, ionic, hydrogen, and van der Waals interactions"}, {"id": "d62f6a96-7dc3-4d2a-840f-9a6bfbcb8a60", "type": "concept", "title": "Hydrophilic, hydrophobic, amphipathic, and charged molecules"}, {"id": "f8e1845e-8e5d-40bf-b19f-8e411db35efb", "type": "concept", "title": "Solubility, membranes, protein folding, and ligand binding"}]}, {"id": "5b9639b9-a198-445e-b3ed-894b20a5122a", "type": "subtopic", "title": "Quantitative chemistry for health science", "description": "Learners practice the calculations that appear in labs, physiology, nutrition, and exercise metabolism.", "children": [{"id": "e7f54e13-d5ad-4325-b1c0-e4a236c2aa10", "type": "concept", "title": "Stoichiometry and limiting reagents"}, {"id": "45750fea-ba17-4ddf-b5ec-b89e44585a87", "type": "concept", "title": "Molarity, dilution, osmolarity, and percent solutions"}, {"id": "2379f136-416d-4f23-a4f9-63afac902ba9", "type": "concept", "title": "Energy units, calories, joules, and oxygen-equivalent thinking"}]}]}, {"id": "91579224-4b14-4ebe-8aaa-796c4b57d23c", "type": "topic", "title": "Carbon Bonding, Functional Groups, and Molecular Properties", "description": "Build fluency with the structures and properties that make biological molecules behave the way they do.", "children": [{"id": "a5dc61d3-962b-46ab-923a-9ee78339921a", "type": "subtopic", "title": "Carbon structure and bonding", "description": "Students learn why carbon can build the molecular diversity required for life.", "children": [{"id": "8d468baa-4862-403e-8381-091f709b6b2b", "type": "concept", "title": "Tetrahedral carbon and hybridization"}, {"id": "291644c8-a12f-40f3-9003-4700dfabfbfb", "type": "concept", "title": "Single, double, and triple bonds"}, {"id": "20d864b4-d2a7-49c7-a351-a5d14d3cb60e", "type": "concept", "title": "Chains, rings, branching, and unsaturation"}]}, {"id": "3e36ba92-9c7e-4097-a50f-0b5579117fcd", "type": "subtopic", "title": "Functional groups", "description": "The gist is to recognize the chemical handles that determine biological behavior.", "children": [{"id": "4fac3caa-5577-4f25-91a3-1b3fd7569d8a", "type": "concept", "title": "Alcohols, thiols, amines, carboxylic acids, aldehydes, ketones, esters, amides, phosphates, and sulfhydryls"}, {"id": "d6adbfc5-1b77-4695-b6ec-4a47c7eeca2a", "type": "concept", "title": "Charge, polarity, hydrogen bonding, and reactivity"}, {"id": "94734c16-1db5-469f-b3ab-72c0d9adfc6a", "type": "concept", "title": "Functional groups in carbohydrates, lipids, proteins, and nucleotides"}]}, {"id": "45cd1d73-1d0b-4734-8f83-19ae0bd578ff", "type": "subtopic", "title": "Structure-property relationships", "description": "Students connect molecular form to solubility, membrane crossing, storage, and metabolism.", "children": [{"id": "e79fb3d8-7db2-464e-8e5e-8a41ac3910d1", "type": "concept", "title": "Molecular size and shape"}, {"id": "f9c39a7e-5d95-47dc-9a03-caff36788b09", "type": "concept", "title": "Acid-base behavior and ionization"}, {"id": "85ab1cf3-c658-481c-813b-e38484c33d4c", "type": "concept", "title": "Partitioning between water, blood, cells, membranes, and adipose tissue"}]}]}, {"id": "a6e3d4d2-65d9-4640-9acf-6f1662b95d34", "type": "topic", "title": "Stereochemistry, Isomerism, and Molecular Recognition", "description": "Explain why three-dimensional molecular shape matters for enzymes, receptors, drugs, fuels, and tissues.", "children": [{"id": "24054d0f-cba3-46fc-b7fa-9e896247b827", "type": "subtopic", "title": "Isomers in biology", "description": "Students learn that molecules with the same formula can have very different effects in the body.", "children": [{"id": "138861c2-e695-4e35-8c22-26be0f9dbe74", "type": "concept", "title": "Constitutional isomers"}, {"id": "9d49c267-794c-4b89-b373-4154759de230", "type": "concept", "title": "Cis-trans and E/Z isomerism"}, {"id": "a492b31c-a89d-4a22-acb4-14d447b28a71", "type": "concept", "title": "Chirality, enantiomers, diastereomers, and meso concepts"}]}, {"id": "0613b570-3220-4369-b905-01d287dc6896", "type": "subtopic", "title": "Molecular recognition", "description": "This subtopic explains why enzymes, receptors, transporters, and drugs are shape-selective.", "children": [{"id": "27b90902-e194-4c4e-8f95-e54496a66d80", "type": "concept", "title": "Lock-and-key and induced-fit ideas"}, {"id": "22c72a09-a09e-4f2c-9010-3d37fab43b4b", "type": "concept", "title": "Binding pockets and complementarity"}, {"id": "bd18477b-ce7f-4e46-80a2-012bdc719928", "type": "concept", "title": "Stereospecific metabolism and signaling"}]}, {"id": "3e63da96-8bf4-470b-9b70-b9d91aebd61b", "type": "subtopic", "title": "Applied stereochemistry", "description": "Learners see stereochemistry in nutrition, pharmacology, exercise physiology, and health claims.", "children": [{"id": "34d7a72f-2593-4e41-9fe4-59741785b058", "type": "concept", "title": "D- and L-sugars and amino acids"}, {"id": "d00a95c1-f214-4143-a034-3efc457cabc6", "type": "concept", "title": "Cis and trans fatty acids"}, {"id": "1eece36d-d553-40b9-a918-a759ca7b3b53", "type": "concept", "title": "Lactate, amino acid supplements, and drug examples"}]}]}, {"id": "0240307f-4e2a-4b15-ac52-6f3f94c8d918", "type": "topic", "title": "Organic Reaction Logic and Mechanisms in Biological Context", "description": "Use reaction patterns to understand biochemical transformations rather than memorizing disconnected facts.", "children": [{"id": "353ea227-ea5a-4de7-aeb9-4aeb1b7cf196", "type": "subtopic", "title": "Reaction patterns", "description": "Students learn reaction families as reusable logic for biochemical pathways.", "children": [{"id": "e4f80902-91c6-4d26-840e-4c0331c456e5", "type": "concept", "title": "Substitution, addition, elimination, oxidation-reduction, condensation, and hydrolysis"}, {"id": "d2f66532-4393-4eb7-ae7d-968d4db36f52", "type": "concept", "title": "Nucleophiles, electrophiles, leaving groups, and catalysts"}, {"id": "9905bf70-c2a2-4e5a-bb16-2b63ad37dd22", "type": "concept", "title": "Reaction arrows and mechanism reasoning"}]}, {"id": "c65e8d9e-2e80-457b-81b5-bf6c54f7bd5f", "type": "subtopic", "title": "Biochemical transformations", "description": "The point is to make metabolism feel chemically inevitable rather than memorized.", "children": [{"id": "2833a9f6-3c56-4e5d-8d51-414aca75244c", "type": "concept", "title": "Phosphorylation and dephosphorylation"}, {"id": "690402ed-4f35-44cb-a954-43a827dfd9de", "type": "concept", "title": "Isomerization, cleavage, transfer, carboxylation, and decarboxylation"}, {"id": "dcac32f8-2ee8-4b74-9f97-9d2d8e7bc644", "type": "concept", "title": "Hydrolysis of ATP, glycogen, triglycerides, and proteins"}]}, {"id": "50a4186e-e2eb-46cb-b2d6-ec6b07d358ce", "type": "subtopic", "title": "Reaction conditions in living systems", "description": "Learners compare bench organic chemistry with enzyme-mediated chemistry in cells.", "children": [{"id": "ab3f9f7b-c7ae-421a-b1d3-12aad4c65ceb", "type": "concept", "title": "Aqueous environments, moderate temperatures, and physiological pH"}, {"id": "4a37343d-c680-4c26-9745-f1a78f6bc2dd", "type": "concept", "title": "Enzyme active sites and cofactors"}, {"id": "91ea9927-1c5b-48da-93d2-7d3ab8d76d3e", "type": "concept", "title": "Specificity, regulation, and compartmentalization"}]}]}, {"id": "19912e95-5634-4580-80f7-0c35b1c2774f", "type": "topic", "title": "Water, pH, Buffers, Acids, Bases, and Physiological Chemistry", "description": "Connect acid-base chemistry to blood, muscle, enzymes, exercise intensity, and homeostasis.", "children": [{"id": "65cb22dd-b09d-4d5a-8378-29ad0a3f0841", "type": "subtopic", "title": "Water as biological solvent", "description": "Students learn why water makes life chemistry possible and constrains how biomolecules behave.", "children": [{"id": "144eefe0-cc0a-47c2-9093-9a7cb90031f3", "type": "concept", "title": "Polarity and hydrogen bonding"}, {"id": "59a73faa-9303-4e72-87a8-df6bf441bfc7", "type": "concept", "title": "Hydration shells and hydrophobic effect"}, {"id": "735c3403-2943-4881-bc4a-5c5c0c87f46a", "type": "concept", "title": "Osmosis, tonicity, and cellular volume"}]}, {"id": "a5f31a39-8d8f-457c-b1ad-2d28acfe755b", "type": "subtopic", "title": "Acids, bases, and buffers", "description": "The gist is to connect pH chemistry to enzymes, blood, exercise, and homeostasis.", "children": [{"id": "7fd7f5f4-703c-4842-bc74-e714104f5df0", "type": "concept", "title": "pH, pKa, weak acids, weak bases, and ionization"}, {"id": "8d2b3c71-294c-4f26-b86d-8a9acb33b4c7", "type": "concept", "title": "Henderson-Hasselbalch reasoning"}, {"id": "207a8182-b401-44a8-93dc-d66a13b48a56", "type": "concept", "title": "Bicarbonate, phosphate, protein, and hemoglobin buffers"}]}, {"id": "9d5c2091-66a5-4491-b7ad-5912cc5e67d3", "type": "subtopic", "title": "Exercise acid-base physiology", "description": "Learners connect chemical buffering to high-intensity work and fatigue.", "children": [{"id": "25176ecd-f738-4dc8-9ed9-0914c5786f59", "type": "concept", "title": "Carbon dioxide, ventilation, and bicarbonate"}, {"id": "ac47222f-38d5-4a2e-a878-1ff074a5c1ab", "type": "concept", "title": "Lactate and hydrogen ion misconceptions"}, {"id": "2ef3e05c-94b0-4134-8479-c4ff1bcb85ee", "type": "concept", "title": "Muscle pH, buffering capacity, and training adaptation"}]}]}, {"id": "9ef67c52-1094-4b65-ba64-e8bb296ebef0", "type": "topic", "title": "Carbohydrates, Glycobiology, and Exercise Fuel Availability", "description": "Understand carbohydrate structure, storage, digestion, and use during rest and exercise.", "children": [{"id": "e5777d17-76c9-4b2c-a0ae-fe27fd725637", "type": "subtopic", "title": "Carbohydrate structure", "description": "Students learn how simple chemical differences create different fuels and tissues.", "children": [{"id": "c94575dd-1d54-41a7-84be-18c43c7b4886", "type": "concept", "title": "Monosaccharides, disaccharides, oligosaccharides, and polysaccharides"}, {"id": "c38d9e23-04ef-4ba4-85ff-705ebceb8178", "type": "concept", "title": "Aldoses, ketoses, ring forms, and glycosidic bonds"}, {"id": "c9368a58-8554-40c0-b6c6-0ff17cc6cc76", "type": "concept", "title": "Starch, glycogen, cellulose, and fiber"}]}, {"id": "1edd884d-942d-4a5f-8dd2-36af48ac95eb", "type": "subtopic", "title": "Digestion, absorption, and storage", "description": "This subtopic connects carbohydrate chemistry to blood glucose and exercise readiness.", "children": [{"id": "b7c2be90-9a91-4d27-9bba-0a2f2aaaa0c8", "type": "concept", "title": "Digestive enzymes and intestinal absorption"}, {"id": "9b22129f-71fb-4cbf-a533-60a258612bb2", "type": "concept", "title": "Glucose transport and insulin-responsive uptake"}, {"id": "04daad83-ca81-44cb-b368-85699dd0e38a", "type": "concept", "title": "Glycogen synthesis, storage, and mobilization"}]}, {"id": "7c377874-b704-4b1c-aa6e-9f4ff270e2d2", "type": "subtopic", "title": "Carbohydrates in exercise", "description": "Learners understand why exercise intensity, duration, and diet change carbohydrate demand.", "children": [{"id": "14e562ea-010f-4d67-9d9e-f8dc7d6f9c9b", "type": "concept", "title": "Muscle and liver glycogen"}, {"id": "6d9c4325-d1ae-48c5-8363-2b32eb0641fb", "type": "concept", "title": "Carbohydrate oxidation and sparing"}, {"id": "93b70466-5cca-4527-9819-7a9437c35a6d", "type": "concept", "title": "Fueling, recovery, and low-carbohydrate adaptation debates"}]}]}, {"id": "025a0db6-f7d0-41b9-82e5-6175f9997c82", "type": "topic", "title": "Lipids, Membranes, Signaling, and Fat Metabolism", "description": "Study lipids as membrane materials, hormones and signals, energy stores, and exercise fuels.", "children": [{"id": "b801569f-d927-43e0-bbdc-a87de5300d33", "type": "subtopic", "title": "Lipid classes and properties", "description": "Students learn why lipids are chemically diverse and biologically essential.", "children": [{"id": "772a62a6-8a09-47e0-b8b4-501c302e9364", "type": "concept", "title": "Fatty acids, triglycerides, phospholipids, cholesterol, steroids, and eicosanoids"}, {"id": "d217fa3f-eb4b-4ec2-b96a-857d57eb1dd0", "type": "concept", "title": "Saturation, chain length, cis-trans configuration, and melting behavior"}, {"id": "54488274-b0da-4a54-9a47-ce0a0e60a395", "type": "concept", "title": "Hydrophobic and amphipathic molecules"}]}, {"id": "1d595a55-ffcc-4d38-909e-34cf3dee9d91", "type": "subtopic", "title": "Membranes and signaling", "description": "The point is to connect lipid chemistry to cell structure, transport, and communication.", "children": [{"id": "f03efb8c-20dd-4bd0-9c2b-14f4276ca0f2", "type": "concept", "title": "Membrane bilayers and fluidity"}, {"id": "7af09a33-4f72-4b95-b332-937a0b7cc115", "type": "concept", "title": "Lipid rafts, receptors, transporters, and channels"}, {"id": "bb6327ca-6c0f-41e0-b1c9-e760e8166d84", "type": "concept", "title": "Steroid hormones, prostaglandins, and inflammatory signaling"}]}, {"id": "39646498-8fa0-4acc-b07a-18746456bc68", "type": "subtopic", "title": "Fat as exercise fuel", "description": "Learners trace how stored fat becomes usable energy during rest and exercise.", "children": [{"id": "c58d4d90-61cb-46b3-842d-66a3d5a0fc0b", "type": "concept", "title": "Lipolysis, transport, and albumin"}, {"id": "19601125-8e7c-48c5-bd05-801109e3451a", "type": "concept", "title": "Beta-oxidation and acetyl-CoA production"}, {"id": "e3bbf969-4fe8-4e48-acef-5e3f20c264cf", "type": "concept", "title": "Intensity, duration, training status, and fat oxidation"}]}]}, {"id": "d3b7e033-a521-4d07-b877-47d8f91fd253", "type": "topic", "title": "Amino Acids, Proteins, Structure, and Movement Function", "description": "Link protein chemistry to muscle, enzymes, transporters, connective tissue, and adaptation.", "children": [{"id": "141ec668-c865-41e4-a0d3-3b65627bf906", "type": "subtopic", "title": "Amino acid chemistry", "description": "Students learn the building blocks that drive protein structure and function.", "children": [{"id": "58dd141b-5004-4177-a5e8-cdd6a679b1e1", "type": "concept", "title": "Side-chain classes, charge, polarity, sulfur, and aromaticity"}, {"id": "6116f07d-a840-4407-852f-c9808b676f81", "type": "concept", "title": "Zwitterions, pKa, and buffering"}, {"id": "f5fe818f-9f36-49e8-9116-b8802ce0bf18", "type": "concept", "title": "Essential, nonessential, glucogenic, and ketogenic amino acids"}]}, {"id": "2764da06-6d4b-4da9-ab97-cac2f2ae7966", "type": "subtopic", "title": "Protein structure and folding", "description": "The gist is to see proteins as functional three-dimensional machines.", "children": [{"id": "fbea08e5-9e25-41ac-bda2-12b58683cb72", "type": "concept", "title": "Primary, secondary, tertiary, and quaternary structure"}, {"id": "818d504f-99e2-449c-b7f2-deeed5225b67", "type": "concept", "title": "Hydrogen bonds, ionic interactions, disulfides, and hydrophobic packing"}, {"id": "c0526f14-e282-43d3-9cde-56f30cdb8b6f", "type": "concept", "title": "Denaturation, misfolding, and chaperones"}]}, {"id": "e5b6eeb4-1e1b-4717-a102-5fc0cd748e97", "type": "subtopic", "title": "Proteins in kinesiology", "description": "Learners connect protein chemistry to movement, adaptation, and tissue repair.", "children": [{"id": "7dc3f251-b5d5-4d61-b466-2ca1bff4f45b", "type": "concept", "title": "Actin, myosin, collagen, elastin, hemoglobin, myoglobin, and enzymes"}, {"id": "25a81545-e5a4-4fb3-8070-3ff84ff6206d", "type": "concept", "title": "Muscle protein synthesis and breakdown"}, {"id": "1780516e-d9bd-4e5f-b9af-c06df076d897", "type": "concept", "title": "Training, nutrition, recovery, and injury repair"}]}]}, {"id": "591498cb-e566-4af9-a741-0b15e5f76e26", "type": "topic", "title": "Enzymes, Kinetics, Regulation, and Metabolic Control", "description": "Learn how enzymes accelerate and regulate the biochemical pathways that support movement and health.", "children": [{"id": "307c8d80-77bf-4385-b8b3-eadc4a6cbcc5", "type": "subtopic", "title": "Enzyme function", "description": "Students learn how enzymes make cellular chemistry fast, specific, and regulated.", "children": [{"id": "2bb91c81-8d38-418f-948c-e72ad340bae1", "type": "concept", "title": "Activation energy and transition states"}, {"id": "80dcc6fb-6604-499c-8209-a35c3f420e77", "type": "concept", "title": "Active sites, cofactors, coenzymes, and metal ions"}, {"id": "35766daa-fa84-4474-84c0-4133fc17a25b", "type": "concept", "title": "Specificity, saturation, and catalytic efficiency"}]}, {"id": "96365330-3a6c-444e-a56b-2eda0f444e39", "type": "subtopic", "title": "Kinetics and inhibition", "description": "This subtopic gives students a working model for interpreting enzyme behavior.", "children": [{"id": "09c4c524-81a6-4976-b138-1b2ddf5cdaa7", "type": "concept", "title": "Michaelis-Menten concepts, Km, Vmax, and turnover"}, {"id": "65f15ac2-428f-45d1-b964-ef6a7f36a8bf", "type": "concept", "title": "Competitive, noncompetitive, uncompetitive, and irreversible inhibition"}, {"id": "fb9bc380-0451-432c-b21c-2b0f570fce41", "type": "concept", "title": "Allosteric enzymes and cooperativity"}]}, {"id": "4482eca8-aeca-4c7b-b28e-5f16a5eb883a", "type": "subtopic", "title": "Regulation of metabolism", "description": "Learners connect enzyme control to exercise, fasting, feeding, and training.", "children": [{"id": "c45f30a8-c2b3-4c9e-9ccc-fcc309528f7e", "type": "concept", "title": "Substrate availability and product inhibition"}, {"id": "c567f711-b18f-45cd-b5be-4aaa47525646", "type": "concept", "title": "Covalent modification and phosphorylation"}, {"id": "679b6fcc-cdda-4f56-9f25-64b16b2e1645", "type": "concept", "title": "Hormonal regulation, compartmentalization, and rate-limiting steps"}]}]}, {"id": "d85156a3-d524-46b1-b1dc-e39682b7baa1", "type": "topic", "title": "Nucleic Acids, Gene Expression, and Molecular Adaptation", "description": "Introduce DNA, RNA, protein synthesis, and gene regulation as foundations for training adaptation and health.", "children": [{"id": "d9bcfce9-d17e-40b0-bfc4-6d7f2058e0a7", "type": "subtopic", "title": "DNA and RNA structure", "description": "Students learn the molecular basis of inheritance and protein production.", "children": [{"id": "f0100719-eac2-4091-b5f7-e51c031b83e4", "type": "concept", "title": "Nucleotides, bases, sugars, phosphate backbone, and base pairing"}, {"id": "c3752d8d-9480-4c6c-a7fa-e205f5c60e46", "type": "concept", "title": "DNA double helix and RNA forms"}, {"id": "499430ef-10d7-4410-876e-01102eba5c8f", "type": "concept", "title": "ATP and nucleotide derivatives as energy and signaling molecules"}]}, {"id": "bc3bd2ce-192a-4113-a5f5-8e9f2b986709", "type": "subtopic", "title": "Gene expression", "description": "The point is to understand how molecular information becomes functional protein.", "children": [{"id": "a055538c-d10c-4f05-bf89-286403169b39", "type": "concept", "title": "Replication, transcription, translation, and the genetic code"}, {"id": "e4675ec2-2655-4fcb-bbd9-0d2857e5e70d", "type": "concept", "title": "mRNA, tRNA, rRNA, ribosomes, and post-translational modification"}, {"id": "a9ed5410-318d-45ac-9fee-ede7e93bce40", "type": "concept", "title": "Regulatory elements and gene-expression control"}]}, {"id": "fac01a26-601a-4417-92e8-45a510c558d9", "type": "subtopic", "title": "Adaptation and health relevance", "description": "Learners connect molecular biology to training response, disease risk, and personalized health.", "children": [{"id": "31a16a4f-c669-46d0-b457-33ea0ab9863e", "type": "concept", "title": "Exercise-induced gene expression"}, {"id": "7baf3e16-97de-4d12-812e-9dd61bd1dfa4", "type": "concept", "title": "Mitochondrial biogenesis and muscle phenotype"}, {"id": "8b3d4d2a-177a-440f-9998-071da59e9f99", "type": "concept", "title": "Genetics, epigenetics, nutrigenomics, and ethical limits of prediction"}]}]}, {"id": "fe31e7cf-a26e-4997-bbd6-018201c90984", "type": "topic", "title": "Thermodynamics, Redox Chemistry, ATP, and Bioenergetics", "description": "Explain how energy, electrons, ATP, and coupled reactions drive cellular work.", "children": [{"id": "b60b0bbe-0d64-476e-9f08-ded54a651d91", "type": "subtopic", "title": "Energy principles", "description": "Students learn the thermodynamic rules behind cellular work.", "children": [{"id": "af492826-d87d-473a-94bc-f46dfc164dd5", "type": "concept", "title": "Free energy, enthalpy, entropy, and spontaneity"}, {"id": "2a018901-f94f-49a4-8492-0686b7b96db9", "type": "concept", "title": "Exergonic and endergonic reactions"}, {"id": "ff09abf9-f7ed-4361-8bf7-addefd5ce718", "type": "concept", "title": "Coupled reactions and metabolic directionality"}]}, {"id": "8c53ac70-4684-410b-b1ea-a46f54eced0f", "type": "subtopic", "title": "ATP and high-energy compounds", "description": "The gist is to understand ATP as an energy-transfer currency rather than a simple fuel tank.", "children": [{"id": "c0204194-363b-438f-930a-e43ca6ef5c51", "type": "concept", "title": "ATP hydrolysis and phosphorylation potential"}, {"id": "bf413c6e-e516-49b3-a15a-6d86a2a92cd4", "type": "concept", "title": "Creatine phosphate and rapid energy buffering"}, {"id": "fa336c8d-760e-41af-a043-4fd25d89bf59", "type": "concept", "title": "Substrate-level and oxidative phosphorylation"}]}, {"id": "4796c64f-625e-4510-bde9-9a4ed1e392fe", "type": "subtopic", "title": "Redox chemistry", "description": "Learners connect electron transfer to mitochondrial energy production and oxidative stress.", "children": [{"id": "c7d9ee73-9767-4ee8-9b87-637dfd1748de", "type": "concept", "title": "Oxidation, reduction, electron carriers, NADH, FADH2, and NADPH"}, {"id": "46cb80df-47be-4f78-9095-445a164830b9", "type": "concept", "title": "Redox potential and electron flow"}, {"id": "7a4c2ea5-b6c6-4538-90e1-333431454a4c", "type": "concept", "title": "Reactive oxygen species, antioxidants, and signaling"}]}]}, {"id": "8fd493f8-7b1e-4cb3-8d32-a15ac